// Title: C# unit test that verifies a specific worksheet cell value appears in the HTML output generated by Aspose.Cells
// AI Prompts: Write an NUnit test method that puts a value into cell A1, saves the workbook as HTML to a MemoryStream, reads the HTML string, and asserts the value is present. | Create a MSTest case using Aspose.Cells that exports a workbook to HTML in memory and fails the test if the expected cell text is not found in the HTML content.
// Common Searches: how to assert a cell value in Aspose.Cells HTML export using C# unit test | verify that Aspose.Cells SaveFormat.Html contains specific worksheet data in memory stream | C# unit testing Aspose.Cells HTML output for expected cell text | write a test to check HTML generated by Aspose.Cells includes cell A1 value
// Tags: Aspose.Cells HTML export verification | C# unit test SaveFormat.Html | validate cell value in generated HTML | memory stream workbook save Aspose.Cells | assert worksheet data in HTML output

using System;
using System.IO;
using Aspose.Cells;

namespace AsposeCellsTests
{
    // The example creates a workbook, writes "TestValue" to cell A1, saves it as HTML to a MemoryStream, reads the HTML content, and throws an exception if the expected value is not found, demonstrating how to unit‑test Aspose.Cells HTML export.
    public class HtmlExportTests
    {
        public static void Main()
        {
            try
            {
                CellValue_ShouldAppearInHtmlOutput();
                Console.WriteLine("Test passed.");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Test failed: {ex.Message}");
            }
        }

        public static void CellValue_ShouldAppearInHtmlOutput()
        {
            // Create a new workbook
            var workbook = new Workbook();

            // Access the first worksheet
            var worksheet = workbook.Worksheets[0];

            // Set a specific value in cell A1
            const string expectedValue = "TestValue";
            worksheet.Cells["A1"].PutValue(expectedValue);

            // Save the workbook to HTML using a memory stream
            using (var htmlStream = new MemoryStream())
            {
                workbook.Save(htmlStream, SaveFormat.Html);
                htmlStream.Position = 0; // Reset stream position for reading

                // Read the HTML content as a string
                using (var reader = new StreamReader(htmlStream))
                {
                    string htmlContent = reader.ReadToEnd();

                    // Verify that the expected cell value appears in the HTML output
                    if (!htmlContent.Contains(expectedValue))
                    {
                        throw new InvalidOperationException(
                            $"The HTML output does not contain the expected cell value '{expectedValue}'.");
                    }
                }
            }
        }
    }
}
